import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'

import { AnyPropertyFilter } from '~/types'

import { LocalFilter } from '../entityFilterLogic'
import { actionFilterGroupLogic } from './actionFilterGroupLogic'

export interface NestedFilterLogicProps {
    groupFilterUuid: string
    nestedIndex: number
    typeKey: string
    groupIndex: number
    /** True when the nested filter already carries property filters, so the row starts expanded. */
    initiallyVisible?: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface nestedFilterLogicValues {
    entityFilterVisible: Record<number, boolean>
    filterVisible: boolean
    seededFilterVisible: boolean
    userSetFilterVisible: boolean | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface nestedFilterLogicActions {
    removeNestedFilter: (nestedIndex: number) => {
        nestedIndex: number
    } // actionFilterGroupLogic
    updateNestedFilter: (
        nestedIndex: number,
        updates: Partial<LocalFilter>
    ) => {
        nestedIndex: number
        updates: Partial<LocalFilter>
    } // actionFilterGroupLogic
    updateNestedFilterProperties: (
        nestedIndex: number,
        properties: AnyPropertyFilter[]
    ) => {
        nestedIndex: number
        properties: AnyPropertyFilter[]
    } // actionFilterGroupLogic
    convertFilterToGroup: () => {}
    duplicateFilter: () => {}
    removeLocalFilter: (filter: { index: number }) => {
        filter: {
            index: number
        }
    }
    selectFilter: () => {}
    setEntityFilterVisibility: (
        index: number,
        value: boolean
    ) => {
        index: number
        value: boolean
    }
    updateFilter: (
        filter: Partial<LocalFilter> & {
            index: number
        }
    ) => {
        filter: Partial<LocalFilter> & {
            index: number
        }
    }
    updateFilterMath: () => {}
    updateFilterOptional: () => {}
    updateFilterProperty: (filter: { index: number; properties: AnyPropertyFilter[] }) => {
        filter: {
            index: number
            properties: AnyPropertyFilter[]
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface nestedFilterLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        entityFilterVisible: (filterVisible: boolean, nestedIndex: number) => Record<number, boolean>
        filterVisible: (userSetFilterVisible: boolean | null, seededFilterVisible: boolean) => boolean
    }
}

export type nestedFilterLogicType = MakeLogicType<
    nestedFilterLogicValues,
    nestedFilterLogicActions,
    NestedFilterLogicProps,
    nestedFilterLogicMeta
>

/**
 * Minimal logic for nested filters within an ActionFilterGroup.
 * Implements only the actions required by ActionFilterRow and delegates
 * all updates to the parent actionFilterGroupLogic.
 */
export const nestedFilterLogic = kea<nestedFilterLogicType>([
    path(['scenes', 'insights', 'filters', 'ActionFilter', 'ActionFilterGroup', 'nestedFilterLogic']),
    props({} as NestedFilterLogicProps),
    key((props) => `${props.groupFilterUuid}-${props.nestedIndex}`),

    connect((props: NestedFilterLogicProps) => ({
        actions: [
            actionFilterGroupLogic({
                filterUuid: props.groupFilterUuid,
                typeKey: props.typeKey,
                groupIndex: props.groupIndex,
            }),
            ['updateNestedFilter', 'removeNestedFilter', 'updateNestedFilterProperties'],
        ],
    })),

    actions({
        updateFilter: (filter: Partial<LocalFilter> & { index: number }) => ({ filter }),
        removeLocalFilter: (filter: { index: number }) => ({ filter }),
        updateFilterProperty: (filter: { index: number; properties: AnyPropertyFilter[] }) => ({ filter }),
        setEntityFilterVisibility: (index: number, value: boolean) => ({ index, value }),
        // Stub actions that ActionFilterRow may call but we don't need for nested filters
        selectFilter: () => ({}),
        updateFilterOptional: () => ({}),
        updateFilterMath: () => ({}),
        duplicateFilter: () => ({}),
        convertFilterToGroup: () => ({}),
    }),

    reducers(({ props }) => ({
        // Only a user toggle writes here, so the choice the user made for this row wins over the seed.
        userSetFilterVisible: [
            null as boolean | null,
            {
                setEntityFilterVisibility: (_, { value }) => value,
            },
        ],
        // The logic stays mounted while a row gains its first property filter, so `initiallyVisible`
        // alone cannot open that row. The seed never goes back to false, which keeps the "Add filter"
        // button on screen when the user removes the last filter.
        seededFilterVisible: [
            props.initiallyVisible ?? false,
            {
                updateNestedFilterProperties: (state, { nestedIndex, properties }) =>
                    state || (nestedIndex === props.nestedIndex && properties.length > 0),
            },
        ],
    })),

    selectors({
        filterVisible: [
            (s) => [s.userSetFilterVisible, s.seededFilterVisible],
            (userSetFilterVisible: boolean | null, seededFilterVisible: boolean): boolean =>
                userSetFilterVisible ?? seededFilterVisible,
        ],
        entityFilterVisible: [
            (s, p) => [s.filterVisible, p.nestedIndex],
            (filterVisible: boolean, nestedIndex: number): Record<number, boolean> => ({
                [nestedIndex]: filterVisible,
            }),
        ],
    }),

    listeners(({ actions, props }) => ({
        updateFilter: ({ filter }) => {
            actions.updateNestedFilter(props.nestedIndex, filter)
        },
        removeLocalFilter: () => {
            actions.removeNestedFilter(props.nestedIndex)
        },
        updateFilterProperty: ({ filter }) => {
            actions.updateNestedFilterProperties(props.nestedIndex, filter.properties)
        },
    })),
])
